// 命令上下文先保留原错误与提供人，等领域守卫走到Interaction.validate时再报告，不抢未知来源/能力首错。
InteractionContext command_context(const BoundaryValue* value){InteractionContext out;if(!value||!value->as<BoundaryValue::Dict>()){out.input_error="MissingInteractionContext";return out;}auto copy=[&](const char* key,StableId& target){if(const auto* field=value->find(key))if(const auto* text=field->as<StableId>())target=*text;};copy("place_id",out.place_id);copy("provider_actor_id",out.provider_actor_id);copy("role_id",out.role_id);if(const auto* kind=value->find("kind"))if(const auto* name=kind->as<StableId>();name&&*name=="encounter"){out.kind=*name;if(const auto* id=value->find("encounter_id"))if(const auto* text=id->as<StableId>())out.encounter_id=*text;return out;}try{return interaction_codec::decode_context(*value,"params/context");}catch(const boundary::DecodeFailure&){out.input_error="InvalidInteractionContext";return out;}}
// 可选字段保留存在位，避免把旧档的缺省字段重写成显式零值。
void optional_int(const BoundaryValue& v,const char* key,std::optional<Integer>& out){if(auto* p=v.find(key))out=integer(*p,key);}
EscortProgress escort(const BoundaryValue& v){fields(v,{"departed","arrival_tick","battle_ids","failure","failed_tick"},{},"escort");return {get_bool(v,"departed","escort"),get_int(v,"arrival_tick","escort"),strings(field(v,"battle_ids","escort"),"escort/battle_ids"),get_string(v,"failure","escort"),get_int(v,"failed_tick","escort"),order(v)};}

TaskAction action(const BoundaryValue& v){fields(v,{"offer_id","task_id","context"},{"reward","kind"},"task_action");TaskAction a;a.offer_id=get_string(v,"offer_id","task_action");a.task_id=get_string(v,"task_id","task_action");a.context=interaction_codec::decode_context(field(v,"context","task_action"),"task_action/context");optional_int(v,"reward",a.reward);if(auto* kind=v.find("kind"))a.source_kind=string(*kind,"task_action/kind");a.field_order=order(v);return a;}

