Outcome<bool> emit_task_action_payload_fields(ProjectionWriter& out,const TaskState& s,const ActionCoreView& action){
    const auto* p=s.actions.find(action.id);const bool owned=action.kind=="accept_offer"||action.kind=="report_offer"||action.kind=="deliver_message";
    if(!owned){if(p)return {false,{},common_failure("TaskActionKindMismatch").error};return {true,false,{}};}
    if(!p)return {false,{},common_failure("MissingTaskActionPayload").error};auto status=emit_task_action_fields(out,*p);return {status.ok,status.ok,status.error};
}
Outcome<bool> emit_task_fact_payload_fields(ProjectionWriter& out,const TaskState& s,const FactRecord& fact){
    const auto* escort=s.facts.find(fact.id);const auto* transfer=s.transfers.find(fact.id);const auto* delivery=s.deliveries.find(fact.id);
    const bool owned=fact.kind=="escort_arrival"||fact.kind=="task_transfer"||fact.kind=="task_delivery";
    if(!owned){if(escort||transfer||delivery)return {false,{},common_failure("TaskFactKindMismatch").error};return {true,false,{}};}
    if(fact.domain!="tasks"||static_cast<int>(escort!=nullptr)+static_cast<int>(transfer!=nullptr)+static_cast<int>(delivery!=nullptr)!=1)return {false,{},common_failure("MissingTaskFactPayload").error};
    Status status;if(fact.kind=="escort_arrival"&&escort)status=emit_escort_arrival_fields(out,*escort);else if(fact.kind=="task_transfer"&&transfer&&transfer->id==fact.id)status=emit_transfer_fields(out,*transfer,s.exact_quantities);else if(fact.kind=="task_delivery"&&delivery&&delivery->id==fact.id)status=emit_delivery_fields(out,*delivery,s.exact_quantities);else return {false,{},common_failure("TaskFactKindMismatch").error};return {status.ok,status.ok,status.error};
}
Status validate_task_original_payload_headers(const CommonStore& common,const TaskState& state){
    std::size_t actions=0,escorts=0,transfers=0,deliveries=0,cargo=0;
    for(const auto& row:common.state().actions.rows()){
        const auto& action=row.second;
        const bool owned=action.kind=="accept_offer"||action.kind=="report_offer"||action.kind=="deliver_message";
        const auto* payload=state.actions.find(row.first);
        if(!owned){if(payload)return common_failure("TaskActionKindMismatch",row.first,ErrorKind::internal);continue;}
        if(action.id!=row.first||!payload)return common_failure("MissingTaskActionPayload",row.first,ErrorKind::internal);
        ++actions;
    }
    if(actions!=state.actions.size())return common_failure("TaskActionPayloadCoverageMismatch",{},ErrorKind::internal);
    for(const auto& row:common.state().facts.rows()){
        const auto& header=row.second;
        const auto* escort=state.facts.find(row.first);const auto* transfer=state.transfers.find(row.first);
        const auto* delivery=state.deliveries.find(row.first);const auto* disposition=state.cargo_dispositions.find(row.first);
        const bool owned=header.kind=="escort_arrival"||header.kind=="task_transfer"||header.kind=="task_delivery"||header.kind=="task_cargo_disposition";
        if(!owned){if(escort||transfer||delivery||disposition)return common_failure("TaskFactKindMismatch",row.first,ErrorKind::internal);continue;}
        if(header.id!=row.first||header.domain!="tasks"||static_cast<int>(escort!=nullptr)+static_cast<int>(transfer!=nullptr)+static_cast<int>(delivery!=nullptr)+static_cast<int>(disposition!=nullptr)!=1)
            return common_failure("TaskFactPayloadCoverageMismatch",row.first,ErrorKind::internal);
        if(header.kind=="escort_arrival"&&escort)++escorts;
        else if(header.kind=="task_transfer"&&transfer&&transfer->id==row.first)++transfers;
        else if(header.kind=="task_delivery"&&delivery&&delivery->id==row.first)++deliveries;
        else if(header.kind=="task_cargo_disposition"&&disposition&&disposition->id==row.first)++cargo;
        else return common_failure("TaskFactKindMismatch",row.first,ErrorKind::internal);
    }
    return escorts==state.facts.size()&&transfers==state.transfers.size()&&deliveries==state.deliveries.size()&&cargo==state.cargo_dispositions.size()
        ?common_success():common_failure("TaskFactPayloadCoverageMismatch",{},ErrorKind::internal);
}
Status emit_task_facts_fields(ProjectionWriter& out,const TaskState& s){
    for(const auto& row:s.facts.rows()){out.object(row.first,[&](auto& w){return emit_escort_arrival_fields(w,row.second);});if(!out.status().ok)return out.status();}
    for(const auto& row:s.transfers.rows()){out.object(row.first,[&](auto& w){return emit_transfer_fields(w,row.second,s.exact_quantities);});if(!out.status().ok)return out.status();}
    for(const auto& row:s.deliveries.rows()){out.object(row.first,[&](auto& w){return emit_delivery_fields(w,row.second,s.exact_quantities);});if(!out.status().ok)return out.status();}return out.status();
}
Status emit_task_root_fields(ProjectionWriter& out,const TaskState& s){return out.object("tasks",[&](auto& w){for(const auto& row:s.tasks.rows()){w.object(row.first,[&](auto& c){return emit_task_record_fields(c,row.second);});if(!w.status().ok)break;}return w.status();});}
Status emit_task_state_fields(ProjectionWriter& out,const TaskState& s){
    emit_task_root_fields(out,s);
    out.object("action_params",[&](auto& w){for(const auto& row:s.actions.rows()){w.object(row.first,[&](auto& c){return emit_task_action_fields(c,row.second);});if(!w.status().ok)break;}return w.status();});
    out.object("facts",[&](auto& w){return emit_task_facts_fields(w,s);});return out.status();
}
BoundaryValue encode_task_state(const TaskState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto status=writer.object("",[&](auto& out){return emit_task_state_fields(out,s);});if(status.ok)status=writer.finish();if(!status.ok){boundary::DecodeFailure failure(status.error.original.code,status.error.original.path);failure.error=status.error;throw failure;}return value;}
Outcome<TaskCommand> decode_task_command(const StableId& kind,const BoundaryValue& params){try{using namespace boundary;if(kind!="accept_offer"&&kind!="report_offer"&&kind!="deliver_message"&&kind!="cancel_task"&&kind!="decline_offer"&&kind!="decline_runtime_offer")return {false,{},common_failure("UnsupportedAction").error};if(kind=="decline_runtime_offer")fields(params,{"offer_ref","need_revision","context"},{"offer_id","kind"},"params");TaskCommand c;c.kind=kind;if(auto* original=params.find("kind")){c.source_kind=string(*original,"params/kind");if(*c.source_kind!=kind)fail("InvalidTaskAction","params/kind");}if(const auto* offer=params.find("offer_id")){if(const auto* value=offer->as<StableId>())c.offer_id=*value;}if(const auto* ref=params.find("offer_ref")){fields(*ref,{"kind","id"},{},"params/offer_ref");OfferRef value;const auto ref_kind=get_string(*ref,"kind","offer_ref");if(ref_kind=="authored")value.kind=OfferRef::Kind::authored;else if(ref_kind=="runtime")value.kind=OfferRef::Kind::runtime;else fail("UnknownOfferRefKind","offer_ref");value.id=get_string(*ref,"id","offer_ref");if(!c.offer_id.empty()&&c.offer_id!=value.id)fail("OfferReferenceMismatch","offer_ref");c.offer_ref=value;c.offer_id=value.id;}if(auto* revision=params.find("need_revision")){c.need_revision=integer(*revision,"need_revision");if(*c.need_revision<1)fail("InvalidNeedRevision","need_revision");}if(auto* quantity=params.find("quantity")){c.quantity=integer(*quantity,"quantity");if(*c.quantity<1)fail("InvalidContractQuantity","quantity");}c.context=command_context(params.find("context"));c.field_order=order(params);return {true,std::move(c),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_task_command_fields(ProjectionWriter& out,const TaskCommand& command){
    if(!command.offer_ref)out.field("offer_id",command.offer_id);
    out.object("context",[&](auto& w){return emit_interaction_context_fields(w,command.context);});
    if(command.offer_ref){out.object("offer_ref",[&](auto& w){w.text("kind",command.offer_ref->kind==OfferRef::Kind::runtime?"runtime":"authored");return w.field("id",command.offer_ref->id);});if(std::find(command.field_order.begin(),command.field_order.end(),"offer_id")!=command.field_order.end())out.field("offer_id",command.offer_id);}
    if(command.need_revision)out.field("need_revision",*command.need_revision);if(command.quantity)out.field("quantity",*command.quantity);if(command.source_kind)out.field("kind",*command.source_kind);return out.order_fields(command.field_order);
}
BoundaryValue encode_task_command(const TaskCommand& command){BoundaryValue value;BoundaryProjectionWriter writer(value);auto status=writer.object("",[&](auto& out){return emit_task_command_fields(out,command);});if(status.ok)status=writer.finish();if(!status.ok){boundary::DecodeFailure failure(status.error.original.code,status.error.original.path);failure.error=status.error;throw failure;}return value;}
BoundaryValue encode_task_quote(const TaskQuote& q){using namespace boundary;auto v=obj({{"ok",{true}},{"duration",{q.duration}}});auto& out=std::get<BoundaryValue::Dict>(v.data);if(q.task_id)out.emplace_back("task_id",BoundaryValue{*q.task_id});out.emplace_back("context",interaction_codec::encode_context(q.context));if(q.reward)out.emplace_back("reward",BoundaryValue{*q.reward});if(q.delivery_quantity)out.emplace_back("quantity",BoundaryValue{*q.delivery_quantity});if(q.restitution)out.emplace_back("restitution",BoundaryValue{true});if(q.runtime)out.emplace_back("contract_terms",obj({{"need_id",{q.runtime->need_id}},{"need_revision",{q.runtime->need_revision}},{"quantity",{q.runtime->quantity}},{"purchase_budget_cap",{q.runtime->terms.purchase_budget_cap}},{"reward_total",{q.runtime->terms.reward_total}},{"deadline_tick",{q.runtime->terms.deadline_tick}}}));return v;}
Status emit_task_effect_fields(ProjectionWriter& out,const TaskEffect& e){out.field("ok",true);out.field("success",e.success);if(e.task_id)out.field("task_id",*e.task_id);if(e.code)out.field("code",*e.code);if(e.on_unavailable)out.field("on_unavailable",*e.on_unavailable);if(e.retry)out.field("retry",*e.retry);return out.order_fields(e.field_order);}
BoundaryValue encode_task_effect(const TaskEffect& e){BoundaryValue value;BoundaryProjectionWriter writer(value);auto status=writer.object("",[&](auto& out){return emit_task_effect_fields(out,e);});if(status.ok)status=writer.finish();if(!status.ok){boundary::DecodeFailure failure(status.error.original.code,status.error.original.path);failure.error=status.error;throw failure;}return value;}
Outcome<TaskEffect> decode_task_effect(const BoundaryValue& v){try{using namespace boundary;fields(v,{"ok","success"},{"task_id","code","on_unavailable","retry"},"task_effect");if(!get_bool(v,"ok","task_effect"))fail("InvalidTaskResult","task_effect");TaskEffect e;e.success=get_bool(v,"success","task_effect");for(auto entry:{std::pair<const char*,std::optional<StableId>*>{"task_id",&e.task_id},{"code",&e.code},{"on_unavailable",&e.on_unavailable},{"retry",&e.retry}})if(const auto* value=v.find(entry.first))*entry.second=string(*value,"task_effect");e.field_order=order(v);return {true,std::move(e),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
